public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int[] a = new int[n];
        int[] b = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = scanner.nextInt();
        }
        for (int i = 0; i < n; i++) {
            b[i] = scanner.nextInt();
        }
        long res = 0;
        int c = 0;
        for (int i = 0; i < n; i++) {
            if (a[i] != b[i]) {
                c++;
                res += c;
            } else {
                c = 0;
            }
        }
        System.out.println(res);
    }
}
